import { useCallback, useEffect, useMemo } from 'react';

import { TemplateSlide } from 'components';
import { FilterDataAccessor } from 'domain/Filter';
import DOMPurify from 'dompurify';
import { usePageFilterApplied, usePageFilterData, usePageIndexes } from 'hooks';
import {
  CountrySlide,
  EvolutionSlide,
} from 'pages/components/PortfolioBrand/Slides';
import { StyledExportPageSection } from 'shared/Styles/exportPages.styles';

import { BRAND_POWER_BOOK_EXPORT_PAGE_NAME } from '../../../BrandPowerBookExport';
import {
  StyledContent,
  StyledParagraph,
} from '../../../BrandPowerBookExport.styles';
import {
  EXECUTIVE_SUMMARY_INSIGHTS_CONFIG,
  pageSections,
} from '../../../constants';
import { findInsightTexts } from '../../../helpers';
import { usePowerBookCountryData } from '../../../hooks/usePowerBookCountryData/usePowerBookCountryData';
import { usePowerBookPeriods } from '../../../hooks/usePowerBookPeriods/usePowerBookPeriods';
import { InsightRecord } from '../../../types';
import { InsightsSlide } from '../../InsightsSlide';
import { SubCover } from '../../SubCover/SubCover';
import {
  buildCountrySlideProps,
  buildEvolutionInfos,
} from '../CountryInline/utils';

interface CountryViewProps {
  containerRef: React.RefObject<HTMLElement>;
  loadingCallback: (loading: boolean) => void;
  insightsData: InsightRecord[];
  isLoadingInsightsData: boolean;
}

export const CountryView = ({
  containerRef,
  loadingCallback,
  insightsData,
  isLoadingInsightsData,
}: CountryViewProps) => {
  const { dataFilters } = usePageFilterData(BRAND_POWER_BOOK_EXPORT_PAGE_NAME);
  const { applied } = usePageFilterApplied(BRAND_POWER_BOOK_EXPORT_PAGE_NAME);
  const country = FilterDataAccessor.getInstance().getCountry(
    dataFilters,
    applied,
  );
  const countryCode = country?.value as string | undefined;
  const { getPageByName, updateIndexes } = usePageIndexes(containerRef);
  const {
    qtdPeriod: quarterYear,
    ytdPeriod,
    ytdSubCoverLabel,
    qtdCoverPrefix,
  } = usePowerBookPeriods();

  const { qtdData, ytdData, isLoadingCountryData, error } =
    usePowerBookCountryData(countryCode);

  const evolutionInfosQTD = useMemo(() => {
    const infos = buildEvolutionInfos(
      qtdData?.overview,
      qtdData?.overviewMegabrands,
      isLoadingCountryData,
    );
    return [
      {
        ...infos[0],
        evolutionSlideError: error,
        insights: findInsightTexts(insightsData, {
          type: 'Country',
          country: countryCode,
          template: 'Evolution',
          scope: 'None',
          sub_scope: 'None',
          segmented_control: 'None',
          timeframe: 'QTD',
        }),
      },
      {
        ...infos[1],
        evolutionSlideError: error,
        insights: findInsightTexts(insightsData, {
          type: 'Country',
          country: countryCode,
          template: 'Evolution',
          scope: 'None',
          sub_scope: 'Megabrands',
          segmented_control: 'None',
          timeframe: 'QTD',
        }),
      },
    ];
  }, [
    qtdData,
    isLoadingCountryData,
    error,
    findInsightTexts,
    insightsData,
    countryCode,
  ]);

  useEffect(() => {
    loadingCallback(isLoadingCountryData && isLoadingInsightsData);

    if (!isLoadingCountryData && !isLoadingInsightsData) {
      updateIndexes();
    }
  }, [
    isLoadingCountryData,
    isLoadingInsightsData,
    loadingCallback,
    updateIndexes,
  ]);

  const executiveSummaryInsights = useCallback(
    (timeframe: 'QTD' | 'YTD') => {
      const insights = insightsData
        ?.filter(
          (insight) =>
            insight.type === 'Country' &&
            insight.template === 'Executive Summary' &&
            insight.country === countryCode &&
            !!insight.insight_text &&
            insight.insights_title !== 'None' &&
            insight.timeframe === timeframe,
        )
        .sort(
          (a, b) =>
            EXECUTIVE_SUMMARY_INSIGHTS_CONFIG[a.insights_title].indexBadge -
            EXECUTIVE_SUMMARY_INSIGHTS_CONFIG[b.insights_title].indexBadge,
        );

      if (!insights || insights.length === 0) {
        return null;
      }

      return insights;
    },
    [insightsData, countryCode],
  );

  return (
    <>
      {executiveSummaryInsights('QTD') && (
        <StyledExportPageSection
          data-page-name={`${pageSections.countryExecutiveSummaryInsights}-qtd`}
        >
          <TemplateSlide
            enablePngCopy
            title="Executive Summary"
            period={quarterYear}
            page={
              getPageByName(
                `${pageSections.countryExecutiveSummaryInsights}-qtd`,
              )?.index
            }
            countryId={countryCode}
            headerDivider={false}
            dataTestId={`${pageSections.countryExecutiveSummaryInsights}-qtd`}
          >
            <StyledContent hasSpacing>
              {executiveSummaryInsights('QTD').map(
                (insight) =>
                  !!insight.insight_text && (
                    <InsightsSlide
                      key={insight.insights_title}
                      dataTestId="insights-slide"
                      title={
                        EXECUTIVE_SUMMARY_INSIGHTS_CONFIG[
                          insight.insights_title
                        ].title
                      }
                      content={(insight.insight_text.split('\n') ?? []).map(
                        (alert, index) => (
                          <StyledParagraph
                            key={alert + index}
                            dangerouslySetInnerHTML={{
                              __html: DOMPurify.sanitize(alert),
                            }}
                          />
                        ),
                      )}
                      indexBadge={
                        EXECUTIVE_SUMMARY_INSIGHTS_CONFIG[
                          insight.insights_title
                        ].indexBadge
                      }
                    />
                  ),
              )}
            </StyledContent>
          </TemplateSlide>
        </StyledExportPageSection>
      )}

      <StyledExportPageSection data-page-name={pageSections.countryTrends}>
        <TemplateSlide
          enablePngCopy
          title={`${String(country?.label)} ABI: Power Evolution`}
          period={quarterYear}
          footnotes={
            applied.country === 'DOM' ? (
              <>
                <b>About results:</b> Results before 2022 exclude the Dominican
                Republic in the survey.
              </>
            ) : undefined
          }
          page={getPageByName(pageSections.countryTrends)?.index}
          countryId={countryCode}
          headerDivider={false}
          dataTestId={pageSections.countryTrends}
        >
          <StyledContent>
            <EvolutionSlide
              evolutionSlideInfos={evolutionInfosQTD}
              dataTestId="slide-evolution-country"
            />
          </StyledContent>
        </TemplateSlide>
      </StyledExportPageSection>

      <StyledExportPageSection data-page-name={pageSections.countryQtdCover}>
        <SubCover
          title={quarterYear}
          countryCode={countryCode ?? ''}
          countryName={String(country?.label)}
        />
      </StyledExportPageSection>

      <StyledExportPageSection data-page-name={pageSections.countryPerformance}>
        <TemplateSlide
          enablePngCopy
          title={`${country?.label} ABI: ${qtdCoverPrefix} Performance`}
          period={quarterYear}
          footnotes=""
          page={getPageByName(pageSections.countryPerformance)?.index}
          countryId={countryCode}
          headerDivider={false}
          dataTestId={pageSections.countryPerformance}
        >
          <StyledContent>
            <CountrySlide
              {...buildCountrySlideProps(qtdData, false)}
              loading={isLoadingCountryData}
              error={error}
              alerts={findInsightTexts(insightsData, {
                type: 'Country',
                scope: 'None',
                template: 'Brands',
                sub_scope: 'None',
                segmented_control: 'ABI',
                timeframe: 'QTD',
                country: countryCode,
              })}
              dataTestId="slide-country-abi"
            />
          </StyledContent>
        </TemplateSlide>
      </StyledExportPageSection>

      <StyledExportPageSection
        data-page-name={pageSections.countryCompetitorPerformance}
      >
        <TemplateSlide
          enablePngCopy
          title={`${country?.label} Competition: ${qtdCoverPrefix} Performance`}
          period={quarterYear}
          footnotes=""
          page={getPageByName(pageSections.countryCompetitorPerformance)?.index}
          countryId={countryCode}
          headerDivider={false}
          dataTestId={pageSections.countryCompetitorPerformance}
        >
          <StyledContent>
            <CountrySlide
              {...buildCountrySlideProps(qtdData, true)}
              loading={isLoadingCountryData}
              error={error}
              alerts={findInsightTexts(insightsData, {
                type: 'Country',
                scope: 'None',
                template: 'Brands',
                sub_scope: 'None',
                segmented_control: 'Competitor',
                timeframe: 'QTD',
                country: countryCode,
              })}
              dataTestId="slide-country-competitor"
            />
          </StyledContent>
        </TemplateSlide>
      </StyledExportPageSection>

      <StyledExportPageSection data-page-name={pageSections.countryYtdCover}>
        <SubCover
          title={ytdSubCoverLabel}
          countryCode={countryCode ?? ''}
          countryName={String(country?.label)}
        />
      </StyledExportPageSection>

      {executiveSummaryInsights('YTD') && (
        <StyledExportPageSection
          data-page-name={`${pageSections.countryExecutiveSummaryInsights}-ytd`}
        >
          <TemplateSlide
            enablePngCopy
            title="Executive Summary"
            period={quarterYear}
            page={
              getPageByName(
                `${pageSections.countryExecutiveSummaryInsights}-ytd`,
              )?.index
            }
            countryId={countryCode}
            headerDivider={false}
            dataTestId={`${pageSections.countryExecutiveSummaryInsights}-ytd`}
          >
            <StyledContent hasSpacing>
              {executiveSummaryInsights('YTD').map(
                (insight) =>
                  !!insight.insight_text && (
                    <InsightsSlide
                      key={insight.insights_title}
                      dataTestId="insights-slide"
                      title={
                        EXECUTIVE_SUMMARY_INSIGHTS_CONFIG[
                          insight.insights_title
                        ].title
                      }
                      content={(insight.insight_text.split('\n') ?? []).map(
                        (alert, index) => (
                          <StyledParagraph
                            key={alert + index}
                            dangerouslySetInnerHTML={{
                              __html: DOMPurify.sanitize(alert),
                            }}
                          />
                        ),
                      )}
                      indexBadge={
                        EXECUTIVE_SUMMARY_INSIGHTS_CONFIG[
                          insight.insights_title
                        ].indexBadge
                      }
                    />
                  ),
              )}
            </StyledContent>
          </TemplateSlide>
        </StyledExportPageSection>
      )}

      <StyledExportPageSection
        data-page-name={pageSections.countryYtdPerformance}
      >
        <TemplateSlide
          enablePngCopy
          title={`${country?.label} ABI: YTD Performance`}
          period={ytdPeriod}
          footnotes=""
          page={getPageByName(pageSections.countryYtdPerformance)?.index}
          countryId={countryCode}
          headerDivider={false}
          dataTestId={pageSections.countryYtdPerformance}
        >
          <StyledContent>
            <CountrySlide
              {...buildCountrySlideProps(ytdData, false)}
              loading={isLoadingCountryData}
              error={error}
              alerts={findInsightTexts(insightsData, {
                type: 'Country',
                scope: 'None',
                template: 'Brands',
                sub_scope: 'None',
                segmented_control: 'ABI',
                timeframe: 'YTD',
                country: countryCode,
              })}
              dataTestId="slide-country-ytd-abi"
            />
          </StyledContent>
        </TemplateSlide>
      </StyledExportPageSection>

      <StyledExportPageSection
        data-page-name={pageSections.countryYtdCompetitorPerformance}
      >
        <TemplateSlide
          enablePngCopy
          title={`${country?.label} Competition: YTD Performance`}
          period={ytdPeriod}
          footnotes=""
          page={
            getPageByName(pageSections.countryYtdCompetitorPerformance)?.index
          }
          countryId={countryCode}
          headerDivider={false}
          dataTestId={pageSections.countryYtdCompetitorPerformance}
        >
          <StyledContent>
            <CountrySlide
              {...buildCountrySlideProps(ytdData, true)}
              loading={isLoadingCountryData}
              error={error}
              alerts={findInsightTexts(insightsData, {
                type: 'Country',
                scope: 'None',
                template: 'Brands',
                sub_scope: 'None',
                segmented_control: 'Competitor',
                timeframe: 'YTD',
                country: countryCode,
              })}
              dataTestId="slide-country-ytd-competitor"
            />
          </StyledContent>
        </TemplateSlide>
      </StyledExportPageSection>
    </>
  );
};
